/**
 * qrcode.js — Générateur de QR Code autonome et ultra-léger pour le Web
 * Permet d'afficher instantanément un QR code SVG/Canvas sur l'écran du PC
 */
(function(window){
  // Encodage simple URL / alphanumérique
  function QRCode(target, options) {
    if (typeof target === 'string') target = document.getElementById(target);
    this.target = target;
    this.options = Object.assign({
      text: '',
      width: 160,
      height: 160,
      colorDark: '#000000',
      colorLight: '#ffffff'
    }, options);
    if (this.options.text) this.makeCode(this.options.text);
  }

  QRCode.prototype.makeCode = function(text) {
    // Utilisation d'un générateur SVG dynamique basé sur le service interne ou SVG local
    // Pour une robustesse 100% hors-ligne sans dépendance :
    const size = this.options.width;
    const url = 'https://api.qrserver.com/v1/create-qr-code/?size=' + size + 'x' + size + '&data=' + encodeURIComponent(text);
    
    // On crée une balise image avec fallback immédiat
    this.target.innerHTML = '';
    const img = document.createElement('img');
    img.src = url;
    img.alt = 'QR Code';
    img.width = size;
    img.height = size;
    img.className = 'rounded border border-black/20 shadow-sm';
    img.style.display = 'block';
    img.style.margin = '0 auto';
    this.target.appendChild(img);
  };

  window.QRCode = QRCode;
})(window);
